import { expect, type Page } from '@playwright/test';

/** Ordinary navigation waits for the intro; controlled fixtures test its intermediate frames. */
export async function dismissCreatorGuide(page: Page) {
  const guide = page.getByRole('dialog', { name: 'Tank creator guide' });
  for (let count = 0; count < 6 && (await guide.isVisible()); count++)
    await guide.getByRole('button', { name: 'Next creator guide page' }).click();
}
const registered = new WeakSet<Page>();
export async function waitForMainMenu(
  page: Page,
  options: { creatorGuide?: 'keep' | 'dismiss' } = {},
) {
  if (options.creatorGuide !== 'keep' && !registered.has(page)) {
    registered.add(page);
    // Ordinary control flows complete onboarding through its real controls.
    // The dedicated guide tests keep it visible and check every page explicitly.
    await page.addLocatorHandler(page.getByRole('dialog', { name: 'Tank creator guide' }), () =>
      dismissCreatorGuide(page),
    );
  }
  const menu = page.locator('.main-menu');
  await expect(menu).toHaveAttribute('data-menu-parked', 'false', { timeout: 60000 });
  if ((await menu.getAttribute('data-assets')) === 'swf')
    await expect(menu).toHaveAttribute('data-title-frame', '179', { timeout: 60000 });
}
import type { Page } from '@playwright/test';
import type { TankDesign } from '../../src/game/core/types';
/** Read-only observer: geometry checks must not depend on an extra in-game export control. */
export async function readCreatorDesign(page: Page): Promise<TankDesign> {
  const value = await page.locator('.creator').getAttribute('data-design');
  if (!value) throw new Error('The tank creator is not mounted.');
  return JSON.parse(value);
}
/** Coordinates are relative to the creator's tank registration point. */
export async function dropPreview(page: Page, x: number, y: number) {
  // This action also lets the ordinary-flow onboarding handler finish before raw mouse input.
  await page.locator('.creator-part-preview').hover();
  const preview = (await page.locator('.creator-part-preview').boundingBox())!;
  const canvas = (await page.locator('.creator-workspace canvas').boundingBox())!;
  await page.mouse.move(preview.x + preview.width / 2, preview.y + preview.height / 2);
  await page.mouse.down();
  await page.mouse.move(
    canvas.x + ((x + 175) * canvas.width) / 350,
    canvas.y + ((y + 175) * canvas.height) / 350,
    { steps: 12 },
  );
  await page.mouse.up();
}
/** Follow TankScreens' name -> locally saved code -> exit path. */
export async function saveCreator(page: Page, name?: string) {
  await page.getByRole('button', { name: 'SAVE', exact: true }).click();
  const field = page
    .getByRole('dialog', { name: 'Save your tank', exact: true })
    .getByRole('textbox', { name: 'Tank name', exact: true });
  if (name !== undefined || !(await field.inputValue())) await field.fill(name ?? 'Test tank');
  await page
    .getByRole('dialog', { name: 'Save your tank', exact: true })
    .getByRole('button', { name: 'Continue', exact: true })
    .click();
  await page
    .getByRole('dialog', { name: 'Tank saved', exact: true })
    .getByRole('button', { name: 'Exit creator', exact: true })
    .click();
}
export async function exitCreator(page: Page) {
  await page.getByRole('button', { name: 'Exit tank creator', exact: true }).click();
  await page
    .getByRole('dialog', { name: 'Exit tank creator?', exact: true })
    .getByRole('button', { name: 'Exit without saving', exact: true })
    .click();
}

