            ))}
          </>
        ) : p.kind === 'up-arrow' ? (
          <>
            <rect x={x} y={y} width={w} height={h} {...style} />
            <path
              d={`M${x + w / 2} ${y + h * 0.22}L${x + w * 0.8} ${y + h * 0.78}H${x + w * 0.2}Z`}
              fill={style.stroke}
            />
          </>
        ) : p.kind === 'right-arrow' ? (
          <path
