        let errorInk = 0,
          titleInk = 0,
          guestInk = 0,
          menuInk = 0,
          guideInk = 0;
        for (let i = 0; i < error.length; i += 4)
          if (error[i] > 200 && error[i + 1] < 100 && error[i + 2] < 80) errorInk++;
        for (let i = 0; i < title.length; i += 4)
