        for (let i = 0; i < icon.length; i += 4)
          if (icon[i] > 160 && icon[i + 1] > 160 && icon[i + 2] > 160) menuInk++;
        for (let i = 0; i < guide.length; i += 4)
          if (guide[i] < 20 && guide[i + 1] < 20 && guide[i + 2] < 20) guideInk++;
        return {
